const handleSave = async () => {
  if (isPasswordChangeEnabled && !confirmPassword.trim()) {
    const msg = '비밀번호 재입력을 입력해 주세요.';
    if (Platform.OS === 'web') window.alert(msg); else Alert.alert('알림', msg);
    return;
  }
  setIsSaving(true);
  try {
    await updateProfile({ nickname, email, ...(isPasswordChangeEnabled ? { code: password } : {}) });
    setIsPasswordChangeEnabled(false);
    setConfirmPassword('');
  } catch (e: any) {
    const msg = e?.message ?? '저장에 실패했습니다.';
    if (Platform.OS === 'web') window.alert(msg); else Alert.alert('오류', msg);
  } finally {
    setIsSaving(false);
  }
};

